/**
 * Writes docs/content/site-content.md: every page's English copy in one
 * readable file, generated from the same sources the site renders.
 *
 *   npm run content:doc
 *
 * Do not edit the output by hand; edit the source named under each heading.
 */
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

import Markdoc, { type RenderableTreeNode } from "@markdoc/markdoc";

import { notes, projects } from "../src/content/generated.ts";
import { contentLabels } from "../src/data/content-labels.ts";
import {
  additionalLearning,
  certifications,
  cvDocument,
  cvPageCopy,
  education,
  references,
  skillGroups,
  timeline,
} from "../src/data/cv.ts";
import { evidenceItems } from "../src/data/experience.ts";
import { homeContent } from "../src/data/home.ts";
import { noiInterpretations, noiSectionContent } from "../src/data/noi.ts";
import { aboutPageContent, contactPageContent } from "../src/data/pages.ts";
import {
  atelierAreas,
  notesPageContent,
} from "../src/data/supporting-content.ts";
import { socialLinks } from "../src/config/social.ts";

const root = process.cwd();
const outputFile = path.join(root, "docs/content/site-content.md");
const messages = JSON.parse(
  await readFile(path.join(root, "src/messages/en.json"), "utf8"),
) as {
  pages: Record<
    string,
    {
      heading: string;
      description: string;
      metaTitle?: string;
      metaDescription?: string;
    }
  >;
  footer: Record<string, string>;
};

const out: string[] = [];
const line = (text = "") => out.push(text);
const source = (...files: string[]) =>
  line(`_Source: ${files.map((file) => `\`${file}\``).join(", ")}_\n`);
const field = (label: string, value?: string) => {
  if (value) line(`- **${label}:** ${value}`);
};
const bullets = (items: readonly string[] | undefined) => {
  for (const item of items ?? []) line(`- ${item}`);
};

function pageMeta(key: string) {
  const page = messages.pages[key];
  if (!page) return;
  field("Page title (h1)", page.heading);
  field("Intro", page.description);
  field("SEO title", page.metaTitle);
  field("SEO description", page.metaDescription);
  line();
}

/** Markdoc render tree → plain Markdown, enough to read the note. */
function toMarkdown(node: RenderableTreeNode): string {
  if (typeof node === "string") return node;
  if (Array.isArray(node)) return node.map(toMarkdown).join("");
  if (!Markdoc.Tag.isTag(node)) return "";
  const inner = node.children.map(toMarkdown).join("");
  switch (node.name) {
    case "h1":
    case "h2":
    case "h3":
    case "h4":
      return `\n#### ${inner}\n\n`;
    case "p":
      return `${inner}\n\n`;
    case "li":
      return `- ${inner.trim()}\n`;
    case "ul":
    case "ol":
      return `${inner}\n`;
    case "blockquote":
      return `> ${inner.trim()}\n\n`;
    case "strong":
      return `**${inner}**`;
    case "em":
      return `_${inner}_`;
    case "code":
      return `\`${inner}\``;
    case "a":
      return `[${inner}](${String(node.attributes.href ?? "")})`;
    case "img":
      return `![${String(node.attributes.alt ?? "")}](${String(node.attributes.src ?? "")})\n\n`;
    default:
      return inner;
  }
}

const home = homeContent.en;
const labels = contentLabels.en;
const cv = cvPageCopy.en;
const about = aboutPageContent.en;
const contact = contactPageContent.en;
const notesPage = notesPageContent.en;

line("# Site Content (English)");
line();
line(
  "All English copy on the site, page by page. **Generated by `npm run content:doc`. Do not edit this file.** Change the source named under each heading. Work and notes are edited in the admin panel (`/keystatic`). Norwegian and Turkish copy sits beside the English in the same sources.",
);
line();

line("## Everywhere");
source("src/config/social.ts", "src/messages/en.json");
line("**Contact links**");
for (const link of socialLinks)
  line(`- ${link.label}: ${link.href.replace(/^mailto:/u, "")}`);
line();
line("**Footer**");
for (const value of Object.values(messages.footer)) line(`- ${value}`);
line();

line("## Home `/en`");
source("src/data/home.ts", "src/data/experience.ts");
pageMeta("home");
line("### Hero");
field("Eyebrow", home.eyebrow);
field("Name", home.heading);
field("Role", home.role);
field("Position", home.position);
field("Support line", home.support);
field("Buttons", `${home.primaryAction} · ${home.secondaryAction}`);
line();
line("### Manifesto");
line(`**${home.manifestoTitle}**`);
line();
line(home.manifestoText);
line();
const noi = noiSectionContent.en;
line(`### ${noi.title}`);
source("src/data/noi.ts");
line(`**${noi.tagline}**`);
line();
for (const paragraph of noi.paragraphs) {
  line(paragraph);
  line();
}
line(`**${noi.eyebrow}** (language tabs EN / NO / TR; ${noi.meaningNote})`);
line();
for (const reading of Object.values(noiInterpretations)) {
  line(
    `- ${reading.tab}: ${reading.letters.map((item) => `${item.letter} — ${item.word} (${item.line})`).join(" · ")}`,
  );
}
line();
line(`### ${home.selectedWorkTitle}`);
line(home.selectedWorkDescription);
line();
for (const project of projects.filter((item) => item.featured)) {
  line(`- ${project.content.en.title}`);
}
line(`- _Link:_ ${home.allWorkAction}`);
line();
line(`### ${home.expertiseTitle}`);
for (const item of evidenceItems) {
  line(`- **${item.content.en.title}:** ${item.content.en.description}`);
}
line();
line(`### ${home.disciplinesTitle}`);
for (const discipline of home.disciplines) {
  line(
    `- **${discipline.title}:** ${discipline.description} _(${discipline.action})_`,
  );
}
line();
line(`### ${home.notesTitle}`);
line(home.notesDescription);
line();
line(
  `_Shows the newest published note. Links: ${home.notesAction} · ${home.mediumAction}_`,
);
line();
line(`### ${home.atelierTitle}`);
line(home.atelierDescription);
line();
bullets(home.atelierItems);
line(`- _Link:_ ${home.atelierAction}`);
line();
line(`### ${home.aboutTitle}`);
line(`**${home.aboutLead}**`);
line();
line(home.aboutDescription);
line();
line(`_Link:_ ${home.aboutAction}`);
line();
line(`### ${home.contactTitle}`);
line(home.contactDescription);
line();
line(`_Buttons:_ ${home.contactAction} · ${home.cvAction}`);
line();

line("## Work `/en/work`");
source("content/projects/*.json (admin panel → Work)");
pageMeta("work");
for (const project of projects) {
  const content = project.content.en;
  line(`### ${content.title}${project.featured ? " ★ featured" : ""}`);
  line(`\`/en/work/${project.slug}\``);
  line();
  field("Summary", content.summary);
  field("Description", content.description);
  field("Role", content.role);
  field("Organization", content.organization);
  field("Period", content.period);
  field("Location", content.location);
  field("Status", content.status);
  field("Category", labels.category[project.category]);
  field("Technologies", project.technologies.join(", "));
  field("Disciplines", project.disciplines.join(", "));
  field("Live site", project.externalUrl);
  field("Repository", project.repositoryUrl);
  field("Cover", project.coverImage);
  if (project.confidential) field("Confidential", "yes, anonymized");
  const languages = project.availableLocales.join(", ");
  if (languages !== "en, no, tr") field("Published languages", languages);
  for (const [label, items] of [
    ["Responsibilities", content.responsibilities],
    ["Challenges", content.challenges],
    ["Decisions", content.decisions],
    ["Outcomes", content.outcomes],
    ["Lessons", content.lessons],
  ] as const) {
    if (items?.length) {
      line(`- **${label}:**`);
      for (const item of items) line(`  - ${item}`);
    }
  }
  line();
}

line("## Notes `/en/notes`");
source(
  "src/data/supporting-content.ts",
  "content/notes/*.mdoc (admin panel → Blog)",
);
pageMeta("notes");
field("Meta line", notesPage.introMeta);
field("List heading", notesPage.featuredTitle);
field("Topics heading", notesPage.topicsTitle);
field("Topics", notesPage.topics.join(" · "));
field("Medium box", `${notesPage.mediumTitle}: ${notesPage.mediumDescription}`);
line();
for (const note of notes) {
  line(`### ${note.title}`);
  line(
    `\`/${note.language}/notes/${note.slug}\` · ${note.category} · ${note.publishedAt} · ${note.readingMinutes} min`,
  );
  line();
  line(`_${note.description}_`);
  line();
  line(toMarkdown(note.body).trim());
  line();
}

line("## Atelier `/en/atelier`");
source("src/data/supporting-content.ts");
pageMeta("atelier");
for (const area of atelierAreas) {
  line(`### ${area.title.en}`);
  line(area.body.en);
  line();
  line(
    area.images.length
      ? `_${area.images.length} photo(s)_`
      : "_No photos yet (none shown)._",
  );
  line();
}

line("## About `/en/about`");
source("src/data/pages.ts");
pageMeta("about");
field("Meta line", about.introMeta);
line();
for (const section of about.sections) {
  line(`### ${section.title}`);
  if (section.lead) line(`**${section.lead}**\n`);
  line(section.body);
  line();
}
line(`### ${about.closingTitle}`);
line(about.closingBody);
line();
line(`_Button:_ ${about.cvAction}`);
line();

line("## CV `/en/cv`");
source("src/data/cv.ts");
pageMeta("cv");
field("Eyebrow", cv.eyebrow);
field(
  "Download button",
  cvDocument.href ? cv.downloadAction : "hidden (no PDF yet)",
);
line();
line(`### ${cv.timelineTitle}`);
for (const entry of timeline) {
  const detail = entry.detail ? ` (${entry.detail.en})` : "";
  line(
    `- **${entry.period}** · ${cv.kinds[entry.kind]} · ${entry.organization.en} — ${entry.role.en}${detail}`,
  );
  if (entry.description) line(`  - ${entry.description.en}`);
}
line();
line(`### ${cv.skillsTitle}`);
line(cv.skillsNote);
line();
for (const group of skillGroups)
  line(`- **${group.title.en}:** ${group.skills.join(", ")}`);
line();
line(`### ${cv.educationTitle}`);
for (const item of education) line(`- **${item.title.en}:** ${item.detail.en}`);
line();
line(`### ${cv.certificationsTitle}`);
for (const item of certifications) {
  line(
    `- ${item.name} · ${item.issuer}${item.note ? ` · ${item.note.en}` : ""}`,
  );
}
line();
line(`**${cv.additionalLearning}**`);
line();
for (const item of additionalLearning) line(`- ${item.name} · ${item.issuer}`);
line();
line(`### ${cv.referencesTitle}`);
line(cv.referencesDescription);
line();
for (const reference of references) {
  line(
    `- **${reference.organization}** · ${reference.field.en}: ${reference.description.en}`,
  );
}
line();
line(`### ${cv.contactTitle}`);
line(cv.contactDescription);
line();

line("## Contact `/en/contact`");
source("src/data/pages.ts", "src/config/social.ts");
pageMeta("contact");
field("Meta line", contact.introMeta);
field("Text", contact.description);
field("Links heading", labels.contactLinks);
field("Notice", labels.noFormNotice);
field("Button", contact.cvAction);
line();

await writeFile(
  outputFile,
  `${out
    .join("\n")
    .replace(/\n{3,}/gu, "\n\n")
    .trim()}\n`,
);
console.log(`content doc: ${path.relative(root, outputFile)}`);
